-- 비용 기준 후보 배포 전 읽기안 v2 (총괄 v1.192 §2-5) — 읽기 전용 SELECT 만. 개발 세션은 운영에서 실행하지 않았다.
-- 조회문은 후보 d81c3f2f 의 OrderRepository 상수·@Query 원문을 기계적으로 풀어 만들었다(gen_predeploy.py). :since = now() - 30일.
-- 실행 시점·사람·출처는 별도 승인. 결과는 개수·합계만 남기고 행 원문은 필요할 때만.
-- v1(dec-costbasis-20261119/predeploy_read.sql)의 R3 설명(최근5건·DYNAMIC started_at)은 SQL에 없었고 NULL 원가 집계도 제품과 달랐다 — v2 로 대체.

-- R1. 전역 관문의 판정 불가 수(30일, 제품 countRealSessionCostUndeterminedSince 그대로). 0 이 아니면 배포 직후 그 종류의 신규 REAL 진입이 거절된다.
--     해제: 확정 원천이 정산/정정으로 갖춰지면 다음 조회에서 빠진다. 원천이 끝내 없으면 30일 창에서 빠질 때까지 전역 관문은 거절.
SELECT k.kind, (SELECT (SELECT COUNT(*) FROM "order" o   WHERE o.side = 'SELL' AND o.session_id IS NOT NULL AND o.session_kind = k.kind   AND o.sell_applied_at IS NOT NULL AND o.sell_applied_at >= (now() - interval '30 days')   AND (NOT (o.applied_executed_funds IS NOT NULL AND o.applied_paid_fee IS NOT NULL AND o.filled_quantity IS NOT NULL AND o.filled_quantity > 0)        OR NOT EXISTS (SELECT 1 FROM (SELECT bo.position_id, SUM(bo.applied_executed_funds + bo.applied_paid_fee) AS cost, SUM(bo.filled_quantity) AS qty FROM "order" bo WHERE bo.side = 'BUY' AND bo.position_id IS NOT NULL AND bo.filled_quantity > 0 GROUP BY bo.position_id HAVING COUNT(*) = COUNT(bo.applied_executed_funds) AND COUNT(*) = COUNT(bo.applied_paid_fee)) b WHERE b.position_id = o.position_id))) + (SELECT COUNT(*) FROM position p   WHERE p.session_kind = k.kind AND p.session_id IS NOT NULL AND p.status = 'CLOSED'   AND p.closed_at IS NOT NULL AND p.closed_at >= (now() - interval '30 days')   AND ((SELECT COALESCE(SUM(bq.filled_quantity), 0) FROM "order" bq        WHERE bq.position_id = p.id AND bq.side = 'BUY' AND bq.filled_quantity > 0)     > (SELECT COALESCE(SUM(sq.filled_quantity), 0) FROM "order" sq        WHERE sq.position_id = p.id AND sq.side = 'SELL' AND sq.sell_applied_at IS NOT NULL        AND sq.applied_executed_funds IS NOT NULL)     OR (NOT EXISTS (SELECT 1 FROM "order" x WHERE x.position_id = p.id           AND ((x.side = 'BUY' AND x.filled_quantity > 0) OR (x.side = 'SELL' AND x.sell_applied_at IS NOT NULL)))         AND NOT (((COALESCE(p.exit_reason, '') = 'ENTRY_REJECTED' AND COALESCE(p.size, -1) = 0   AND NOT EXISTS (SELECT 1 FROM "order" nx WHERE nx.position_id = p.id)) OR (EXISTS (SELECT 1 FROM "order" nb WHERE nb.position_id = p.id AND nb.side = 'BUY') AND NOT EXISTS (SELECT 1 FROM "order" nb WHERE nb.position_id = p.id AND nb.side = 'BUY'   AND NOT (nb.filled_quantity IS NOT NULL AND nb.filled_quantity = 0 AND (nb.state = 'FAILED'     OR (nb.state = 'CANCELLED' AND (nb.fee_source IS NULL OR nb.cancel_confirmed_at IS NOT NULL))))) AND NOT EXISTS (SELECT 1 FROM "order" ns WHERE ns.position_id = p.id AND ns.side = 'SELL'   AND ns.sell_applied_at IS NOT NULL)))))))) AS undetermined_30d
FROM (VALUES ('LIVE'), ('DYNAMIC')) k(kind);

-- R2. 전역 손실 합(30일, 제품 두 식 그대로 — 판정 불가 행은 합에 없고 R1 이 센다).
SELECT 'LIVE' AS kind, (SELECT COALESCE(SUM(pnl), 0) FROM ( SELECT o.applied_executed_funds - o.applied_paid_fee - (o.filled_quantity * b.cost) / b.qty AS pnl FROM "order" o JOIN (SELECT bo.position_id, SUM(bo.applied_executed_funds + bo.applied_paid_fee) AS cost, SUM(bo.filled_quantity) AS qty FROM "order" bo WHERE bo.side = 'BUY' AND bo.position_id IS NOT NULL AND bo.filled_quantity > 0 GROUP BY bo.position_id HAVING COUNT(*) = COUNT(bo.applied_executed_funds) AND COUNT(*) = COUNT(bo.applied_paid_fee)) b ON b.position_id = o.position_id WHERE o.side = 'SELL' AND o.session_id IS NOT NULL AND o.session_kind = 'LIVE' AND o.sell_applied_at IS NOT NULL AND o.sell_applied_at >= (now() - interval '30 days') AND o.applied_executed_funds IS NOT NULL AND o.applied_paid_fee IS NOT NULL AND o.filled_quantity IS NOT NULL AND o.filled_quantity > 0) t WHERE pnl < 0) AS loss_30d
UNION ALL
SELECT 'DYNAMIC', (SELECT COALESCE(SUM(pnl), 0) FROM ( SELECT o.applied_executed_funds - o.applied_paid_fee - (o.filled_quantity * b.cost) / b.qty AS pnl FROM "order" o JOIN (SELECT bo.position_id, SUM(bo.applied_executed_funds + bo.applied_paid_fee) AS cost, SUM(bo.filled_quantity) AS qty FROM "order" bo WHERE bo.side = 'BUY' AND bo.position_id IS NOT NULL AND bo.filled_quantity > 0 GROUP BY bo.position_id HAVING COUNT(*) = COUNT(bo.applied_executed_funds) AND COUNT(*) = COUNT(bo.applied_paid_fee)) b ON b.position_id = o.position_id WHERE o.side = 'SELL' AND o.session_id IS NOT NULL AND o.session_kind = 'DYNAMIC' AND o.sell_applied_at IS NOT NULL AND o.sell_applied_at >= (now() - interval '30 days') AND o.applied_executed_funds IS NOT NULL AND o.applied_paid_fee IS NOT NULL AND o.filled_quantity IS NOT NULL AND o.filled_quantity > 0) t WHERE pnl < 0);

-- R3. 세션 연속 손실 입력(제품 조회 범위 그대로: LIVE 는 RUNNING REAL 세션의 CLOSED 전체, DYNAMIC 은 RUNNING REAL 의 started_at 뒤).
--     열: [id, 체결BUY, 원가미상BUY, 매수원가합, 매수수량합, 확정SELL, 매도순대금합, 매도수량합, 필수값미상SELL, 무거래확정] + 세션·시각·저장손익.
--     newest_rank 1 부터 읽어 판정 불가(무거래 아님인데 체결BUY·확정SELL 0, 원가/필수값 미상, 매도수량<매수수량)가 연속 손실 한도 안에 있으면 그 세션 진입 차단.
--     🔴 이 범위는 30일 창과 별개다 — LIVE 는 시간 제한이 없어 30일 뒤에도 차단이 남을 수 있다.
SELECT p.id, (SELECT COUNT(*) FROM "order" b WHERE b.position_id = p.id AND b.side = 'BUY' AND b.filled_quantity > 0), (SELECT COUNT(*) FROM "order" b WHERE b.position_id = p.id AND b.side = 'BUY' AND b.filled_quantity > 0    AND (b.applied_executed_funds IS NULL OR b.applied_paid_fee IS NULL)), (SELECT SUM(b.applied_executed_funds + b.applied_paid_fee) FROM "order" b    WHERE b.position_id = p.id AND b.side = 'BUY' AND b.filled_quantity > 0), (SELECT SUM(b.filled_quantity) FROM "order" b WHERE b.position_id = p.id AND b.side = 'BUY' AND b.filled_quantity > 0), (SELECT COUNT(*) FROM "order" s WHERE s.position_id = p.id AND s.side = 'SELL' AND s.sell_applied_at IS NOT NULL    AND s.applied_executed_funds IS NOT NULL), (SELECT SUM(s.applied_executed_funds - s.applied_paid_fee) FROM "order" s    WHERE s.position_id = p.id AND s.side = 'SELL' AND s.sell_applied_at IS NOT NULL AND s.applied_executed_funds IS NOT NULL), (SELECT SUM(s.filled_quantity) FROM "order" s    WHERE s.position_id = p.id AND s.side = 'SELL' AND s.sell_applied_at IS NOT NULL AND s.applied_executed_funds IS NOT NULL), (SELECT COUNT(*) FROM "order" o WHERE o.position_id = p.id AND o.side = 'SELL' AND o.sell_applied_at IS NOT NULL    AND NOT (o.applied_executed_funds IS NOT NULL AND o.applied_paid_fee IS NOT NULL AND o.filled_quantity IS NOT NULL AND o.filled_quantity > 0)), CASE WHEN ((COALESCE(p.exit_reason, '') = 'ENTRY_REJECTED' AND COALESCE(p.size, -1) = 0   AND NOT EXISTS (SELECT 1 FROM "order" nx WHERE nx.position_id = p.id)) OR (EXISTS (SELECT 1 FROM "order" nb WHERE nb.position_id = p.id AND nb.side = 'BUY') AND NOT EXISTS (SELECT 1 FROM "order" nb WHERE nb.position_id = p.id AND nb.side = 'BUY'   AND NOT (nb.filled_quantity IS NOT NULL AND nb.filled_quantity = 0 AND (nb.state = 'FAILED'     OR (nb.state = 'CANCELLED' AND (nb.fee_source IS NULL OR nb.cancel_confirmed_at IS NOT NULL))))) AND NOT EXISTS (SELECT 1 FROM "order" ns WHERE ns.position_id = p.id AND ns.side = 'SELL'   AND ns.sell_applied_at IS NOT NULL))) THEN 1 ELSE 0 END,
  p.session_kind, p.session_id, p.closed_at, p.realized_pnl AS stored_pnl, p.exit_reason,
  ROW_NUMBER() OVER (PARTITION BY p.session_kind, p.session_id ORDER BY p.closed_at DESC NULLS LAST) AS newest_rank
FROM position p
WHERE p.status = 'CLOSED' AND (
  (p.session_kind = 'LIVE' AND p.session_id IN (SELECT id FROM live_trading_session WHERE status = 'RUNNING' AND session_type = 'REAL'))
  OR (p.session_kind = 'DYNAMIC' AND EXISTS (SELECT 1 FROM dynamic_session d WHERE d.id = p.session_id AND d.status = 'RUNNING'
        AND d.trading_mode = 'REAL' AND (d.started_at IS NULL OR p.closed_at > d.started_at))))
ORDER BY p.session_kind, p.session_id, newest_rank;
